p:wrap;gap:6px 16px;margin-top:12px;font-size:12px;line-height:20px}.member-plans__unavailable{display:block;margin-top:18px;font-size:14px}.member-plans__periods{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.member-plans__periods>button{flex:1 0 25%;min-width:72px;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:62px;padding:8px;margin:0;border-radius:8px;background:#fff;border:1px solid #e4e8ee;line-height:22px;color:#545c68;font-size:14px}.member-plans__periods>button>text:last-child{font-size:12px}.member-plans__periods>button.is-selected{border-color:var(--primary-color,#007aff);color:var(--primary-color,#007aff);font-weight:600}.member-plans__comparison{margin:16px 0;background:#fff;border-radius:8px;overflow:hidden}.member-plans__compare-caption{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:14px 12px;font-size:14px;font-weight:600}.member-plans__compare-caption>text:last-child{font-size:11px;color:#737d8b;font-weight:400}.member-plans__table-scroll{width:100%;box-sizing:border-box}.member-plans__table{box-sizing:border-box}.member-plans__row{display:flex;align-items:stretch;border-top:1px solid #edf0f4;min-height:60px}.member-plans__label{position:sticky;left:0;z-index:1;flex:0 0 100px;width:100px;box-sizing:border-box;display:flex;align-items:center;padding:12px;background:#f8f9fb;font-size:12px;line-height:19px;color:#646e7c;border-right:1px solid #edf0f4}.member-plans__cell{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:4px;flex:0 0 132px;width:132px;box-sizing:border-box;margin:0;padding:12px 8px;background:#fff;color:#303947;line-height:20px;font-size:12px;text-align:center;white-space:normal;overflow-wrap:break-word;border-radius:0}.member-plans__cell.is-selected{background:#f0f6ff}.member-plans__row--head .member-plans__cell{font-size:14px;font-weight:600;min-height:76px}.member-plans__selection{font-size:11px;font-weight:400;color:var(--primary-color,#007aff)}.member-plans__table-note{display:block;padding:12px;font-size:11px;line-height:19px;color:#737d8b}.member-plans__benefits{background:#fff;padding:8px 16px 12px;border-radius:12px;margin-top:16px}.member-plans__benefit-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:44px;width:100%;margin:0;padding:0;background:transparent;border-radius:0;line-height:22px;text-align:left;font-size:15px;font-weight:600;color:#303947}.member-plans__benefit-heading>view{display:flex;align-items:center;gap:6px;flex:none;font-size:12px;font-weight:400;color:#7b8795}.member-plans__benefit{display:flex;align-items:flex-start;gap:10px;padding:8px 0}.member-plans__benefit:last-child{padding-bottom:4px}.member-plans__benefit :deep(.u-icon){flex:none;min-height:22px}.member-plans__benefit>view{min-width:0;flex:1}.member-plans__benefit>view>text{display:block;font-size:14px;line-height:22px;color:#303947}.member-plans__benefit>view>text+text{font-size:12px;line-height:20px;color:#737d8b;margin-top:2px}.member-plans__excluded,.member-plans__cell .is-muted{font-size:12px;color:#87909c}.member-plans button[disabled]{opacity:.6}
</style>
